/**
 * Greenleaf Turkiye - product data contract (generated by scripts/data, hand-maintained here).
 * Shared by the website and the catalog. Changes must be handed over to frontend-mimar (devir notu).
 *
 * Decisions encoded here: K-036 (prices), K-038 (wide catalog, "yakinda"), K-039 (light content for "yakinda"),
 * K-040/K-069 (quiz tags), K-045 (certificates), K-048 (sets are normal products), K-050 (12-root 2-level categories),
 * K-062 (PV on EVERY product incl. "yakinda"), K-065/K-066 (palette + themeHint), K-067 (medical patches published).
 *
 * v2 changes vs v1: see docs/ekip/devir/ (veri-muhendisi -> frontend-mimar).
 *
 * Files: data/products.json (Product[]), data/categories.json (CategoriesFile), data/brands.json (Brand[]),
 *        data/content/to-translate.json (ToTranslateItem[]), data/content/content-ru.json ({ [productId]: raw Russian HTML }, NOT for display).
 */

/** "tr" = sold in Turkey now (can be added to cart). "yakinda" = shown with the "Turkiye'ye yakinda" badge, no price, no cart. */
export type Availability = 'tr' | 'yakinda';

export interface ProductImage {
  /** TR products: local optimised file "/products/<slug>/main.webp" (webp, max 800 px; gallery-2.webp ...), served from /public.
   *  "yakinda" products (and TR products whose download failed): remote URL (global.green-leaf.shop, source "RU"). */
  src: string;
  /** Small remote thumbnail if the source offers one (RU shop: -250x250), else null. */
  thumb: string | null;
  /** "XL" = greenleaf-global.com (xlsx), "RU" = global.green-leaf.shop. */
  source: 'XL' | 'RU';
  /** Only for locally stored images: original remote URL and output size. */
  remote?: string;
  width?: number;
  height?: number;
}

/** K-065/K-066: dominant colours of the product picture. onPrimary is chosen for >= 4.5:1 contrast on primary. Hex "#RRGGBB". */
export interface ProductPalette {
  primary: string;
  secondary: string | null;
  tertiary: string | null;
  onPrimary: string;
}
/** K-065 theme hint. "gold" / "premium" by keyword (gold, золот, 24K, premium, люкс...) or, for sets, by golden palette. Frontend decides the actual theme. */
export type ThemeHint = 'gold' | 'premium' | null;

export interface ConsumerCategoryRef {
  /** Top-level consumer category slug, e.g. "cilt-bakimi". Never null in published data. */
  parent: string;
  /** Child slug within the parent (without the parent prefix), e.g. "serumlar"; null when only the parent is known. */
  child: string | null;
}

/**
 * Quiz tags (K-040). Empty arrays / null for now; filled by the quiz-tagging wave.
 * The allowed vocabularies are intentionally open strings until the user/icerik-editoru fix the lists.
 */
export type ConcernTag = string;
export type SkinTypeTag = string;
export type RoutineStep = string | null;

export interface Certificate {
  /** "iso-22716" | "gmp" | "helal" (K-045). EAEU documents are never used. */
  type: string;
  /** PDF url or local path, filled after expert review. */
  pdf: string | null;
}

export type NeedsReviewFlag =
  | 'name-conflict'            // xlsx vs catalog name disagree in meaning (ENVANTER C-1)
  | 'no-catalog-text'          // TR product without catalog copy (e.g. DAC056)
  | 'no-shop-match'            // TR product whose model code is not on global.green-leaf.shop
  | 'shop-multi-match'         // several shop products share the TR code (lowest shop id used)
  | 'category-from-shop'       // consumer category taken from the shop tree because no catalog category exists
  | 'name-corrupt'             // Russian name contains "???" (source character loss)
  | 'page-not-fetched'         // product page was not crawled; code/description/images are incomplete
  | 'no-model-code'            // product page had no "Модель"
  | 'image-derived-from-thumb' // image URL derived by replacing -250x250 with -800x800
  | 'category-unmapped'
  | 'no-short-description'
  | 'dup-code'                 // the same model code appears on more than one record (variants / duplicates)
  | 'panel-missing'            // TR product present in the xlsx but absent from the panel export (price/PV from xlsx)
  | 'not-in-xlsx'              // TR product present in the panel export only (new product)
  | 'title-tr-missing'         // TR product without a Turkish title (panel title.tr is Russian) -> icerik-editoru
  | 'no-code'                  // panel record without model code
  | 'no-image'                 // no image at all
  | 'pv-missing'               // no PV in any source (panel/xlsx/shop bonus points)
  | 'shop-matched-by-title'    // shop record matched by identical cleaned RU title, not by code
  | 'category-guess'           // consumer category decided by the data engineer from the name (review)
  | 'price-client-not-above-member' // panel "client" tier <= member tier: list price derived as member x LIST_PRICE_MULTIPLIER
  | 'price-client-not-2x'      // panel client tier is above member but not exactly 2x (panel client tier used)
  | 'price-xlsx-mismatch'      // panel and xlsx member prices differ (panel used)
  | 'price-implausible';       // price looks wrong (manual review list in config.mjs)

export interface ProductSource {
  /** global.green-leaf.shop product id (stable key), null for TR products absent from the shop. */
  shopId: number | null;
  shopUrl: string | null;
  /**
   * Source price in RUB. FOR AUDIT ONLY - never display, never convert to TRY, never use in any price calculation (K-036).
   */
  rubPrice: number | null;
  /** Shop bonus points (= PV x 100, verified 35/35 on matched TR products). Kept raw. */
  pointsRu: number | null;
  /** Panel/xlsx id for TR products. */
  panelId: string | number | null;
  /** Panel ids of "/A" duplicates merged into this product. */
  panelMergedIds?: number[];
  /** All panel price tiers in TRY (base = member, client = customer, store/co70/co80 = other tiers; not displayed). */
  panelPriceTiers?: Record<string, number> | null;
  panelPointsTiers?: Record<string, number> | null;
  panelCategory?: number | null;
  /** Raw panel title.tr (may be Russian or differ from the curated title_tr). */
  titlePanelTr?: string | null;
  titleRawPanel?: string | null;
  shopMatch?: 'code' | 'title' | null;
  stockRu: string | null;
  sources: Array<'panel' | 'xlsx' | 'catalog' | 'shop'>;
  /** Original Russian name incl. "(Кол-во в коробке N шт)" (non-TR). */
  titleRawRu?: string;
  titleRawXlsx?: string;
  catalogImage?: string | null;
  catalogCategory?: string | null;
  xlsxCategory?: string;
}

export interface Product {
  /** "gl-<shopId>" for shop products (incl. merged TR ones); "tr-<panelId>" for TR products absent from the shop. */
  id: string;
  /** Unique, Turkish-safe ASCII. Locked in data/slug-lock.json once published. */
  slug: string;
  /** Model code ("Модель"), e.g. "CBB017". Not guaranteed unique (variants "/A"); "" if unknown. */
  code: string;
  /** EAN-13, only for TR products (null for sets and non-TR). */
  barcode: string | null;

  title_ru: string;           // cleaned (box quantity removed); "" for TR products without shop match
  title_tr: string;           // TR products: from catalog. Others: "" until bulk localisation (icerik-editoru)
  shortDescription_ru: string;
  shortDescription_tr: string;

  /** Sub-brand slug (see brands.json). "greenleaf" when none detected. */
  brand: string;
  /** Primary source category path (Russian), shallow -> deep. [] when none. */
  sourceCategory: string[];
  /** All source category paths joined with " > ". */
  sourceCategories: string[];
  /** PROPOSED 2-level consumer mapping (docs/veri/KATEGORI-ESLEME-ONERISI.md). */
  consumerCategory: ConsumerCategoryRef;

  availability: Availability;
  /** List ("Fiyat", TRY) = panel client tier when it is above the member tier, else memberPrice x LIST_PRICE_MULTIPLIER. No rounding to whole lira (K-013). null unless availability === "tr". */
  price: number | null;
  /** Member price ("Uye fiyati", TRY) = panel base tier (xlsx if panel missing). null unless availability === "tr". */
  memberPrice: number | null;
  currency: 'TRY';
  /** How `price` was obtained. */
  priceSource: 'panel-client' | 'derived-x2' | null;
  /** PV (K-062: every product). = panel points.base/100 (TR) or shop bonus points/100 ("yakinda"). null only when no source has points. */
  pv: number | null;
  pvSource: 'panel' | 'xlsx' | 'shop-points' | null;
  /** Units per carton (wholesale info), parsed from "(Кол-во в коробке N шт)". */
  boxQty: number | null;
  /** Display volume/weight text from the catalog, e.g. "100 g". */
  volume: string | null;

  images: ProductImage[];

  // --- quiz tags (K-040): REQUIRED fields, empty for now ---
  concerns: ConcernTag[];
  skinType: SkinTypeTag[];
  routineStep: RoutineStep;

  certificates: Certificate[];
  /** K-065/K-066: null when the product has no usable image. */
  palette: ProductPalette | null;
  themeHint: ThemeHint;
  themeHintSource: 'keyword' | 'palette' | null;
  /** Mechanical part of K-024: Turkish title + >= 1 image (+ price for "tr"). Claim review (TITCK) is a separate human gate. */
  publishReady: boolean;
  needsReview: NeedsReviewFlag[];
  isSet: boolean;

  // --- Turkish content layer (EL, icerik-editoru; data/content/products.tr*.json) ---
  /** Fixed notice keys shown on the PDP (text: ui.tr.json product.notice.*). TR products only; [] otherwise. */
  notices: Array<'cosmetic' | 'supplement' | 'regulated'>;
  /** Ingredients named in the source only (TR products). */
  ingredientsHighlight: string[];
  /** Editor note needing a human/expert check before publishing (R-08). null = none. Internal; never render. */
  contentReview: string | null;
  /** true when the review starts with "regulated" (TITCK-sensitive; expert gate) or notices includes "regulated". */
  regulated: boolean;
  contentSource?: 'EL';

  // --- TR full content (only for availability === "tr"; null/[] otherwise, K-039) ---
  description_tr: string | null;
  features_tr: string[];
  usage_tr: string | null;
  /** For sets: product names inside the set (Turkish, from catalog). */
  setContents_tr: string[];

  _source: ProductSource;
}

export interface ConsumerCategory {
  /** "cilt-bakimi" (parent) or "cilt-bakimi/serumlar" (child). */
  slug: string;
  title_tr: string;
  parent: string | null;
  order: number;
  productCount: number;
  trCount: number;
  icon: string | null;
  image: string | null;
  /** Code/id of the product whose packshot is `image` (TR product preferred; yakinda = remote URL). */
  imageProduct?: string | null;
  description_tr: string | null;
}

export interface SourceCategoryNode {
  id: string;
  level: 1 | 2 | 3;
  parent: string | null;
  title_ru: string;
  path_ru: string[];
  url: string;
  /** Product count shown by the source site (includes sub-categories). */
  productCount: number;
  consumerCategory: ConsumerCategoryRef | null;
}

export interface CategoriesFile {
  consumer: ConsumerCategory[];
  source: SourceCategoryNode[];
}

export interface Brand {
  slug: string;
  title: string;
  aliases: string[];
  /** "greenleaf" for sub-brands, null for the parent brand itself. */
  parent: string | null;
  logo: string | null;
  description_tr: string | null;
  productCount: number;
  trCount: number;
}

export interface ToTranslateItem {
  id: string;
  code: string;
  availability: Availability;
  /** 1 = TR (on sale: full texts), 2 = yakinda (K-039: title + short description only). Sorted by priority. */
  priority: 1 | 2;
  /** Fields the editor must deliver. */
  needs: string[];
  title_ru: string;
  shortDescription_ru: string;
  /** Consumer category in Turkish ("Cilt Bakımı > Serumlar") for context. */
  category: string;
  category_ru: string;
  brand: string;
  volume: string | null;
  /** true when a long raw Russian text exists in data/content/content-ru.json[id]. */
  hasLongRu: boolean;
}
